/**
 * Settings Provider: sets the density of every component below it.
 *
 * @packageDocumentation
 */

export { SettingsProvider } from "./settings-provider";
export type { Settings } from "#/lib/settings/settings-context";

import type { ReactNode } from "react";

import { SettingsContext } from "#/lib/settings/settings-context";
import type { Settings } from "#/lib/settings/settings-context";

export function SettingsProvider({
  children,
  settings,
}: {
  readonly children: ReactNode;
  readonly settings: Settings;
}) {
  return <SettingsContext value={settings}>{children}</SettingsContext>;
}
